     "styleText": "\n/* From Uiverse.io by andrew-demchenk0 - Tags: input, shadow, password */\n.input {\n  --input-focus: #2d8cf0;\n  --font-color: #323232;\n  --font-color-sub: #666;\n  --bg-color: #fff;\n  --main-color: #323232;\n  width: 200px;\n  height: 40px;\n  border-radius: 5px;\n  border: 2px solid var(--main-color);\n  background-color: var(--bg-color);\n  box-shadow: 4px 4px var(--main-color);\n  font-size: 15px;\n  font-weight: 600;\n  color: var(--font-color);\n  padding: 5px 10px;\n  outline: none;\n}\n\n.input::placeholder {\n  color: var(--font-color-sub);\n  opacity: 0.8;\n}\n\n.input:focus {\n  border: 2px solid var(--input-focus);\n}\n",
     "raw": "<input type=\"password\" placeholder=\"Password\" name=\"text\" class=\"input\">\n<style>\n/* From Uiverse.io by andrew-demchenk0 - Tags: input, shadow, password */\n.input {\n  --input-focus: #2d8cf0;\n  --font-color: #323232;\n  --font-color-sub: #666;\n  --bg-color: #fff;\n  --main-color: #323232;\n  width: 200px;\n  height: 40px;\n  border-radius: 5px;\n  border: 2px solid var(--main-color);\n  background-color: var(--bg-color);\n  box-shadow: 4px 4px var(--main-color);\n  font-size: 15px;\n  font-weight: 600;\n  color: var(--font-color);\n  padding: 5px 10px;\n  outline: none;\n}\n\n.input::placeholder {\n  color: var(--font-color-sub);\n  opacity: 0.8;\n}\n\n.input:focus {\n  border: 2px solid var(--input-focus);\n}\n</style>\n"
