    "input": "<input type=\"@type@\" name=\"@uid@-field\" id=\"@uid@-field\" class=\"input\" placeholder=\"@placeholder@\" value=\"@value@\">",
    "button": "<div class=\"input btn @tileClass@\" @selectedAttr@ role=\"button\" tabindex=\"0\">@text@</div>",
    "note": "<p class=\"forgotten\">@text@</p>",
