     "raw": "<div class=\"container\">\n\n       \n    <div class=\"hero\">\n       <form action=\"\" class=\"form\">\n<div class=\"logo\">Instagram</div>\n        <input type=\"email\" name=\"email\" id=\"email\" required=\"\" class=\"input\" placeholder=\"Phone, email address or username\">\n    <input type=\"password\" name=\"password\" id=\"password\" required=\"\" class=\"input\" placeholder=\"Password\">   \n    <input type=\"submit\" value=\"Log in\" class=\"input submit\">\n    <p class=\"forgotten\">Forgotten your login details ? <a href=\"#\">Get help with signing in.</a></p>\n    <div class=\"or\">or</div>\n<div class=\"input btn\">Login with facebook </div>    \n<p class=\"signup\">Don't have an account ? <a href=\"#\">SignUp</a></p>\n</form>\n    </div>\n</div>\n<style>\n/* From Uiverse.io by sameer2malik - Tags: neumorphism, instagram, form */\n.container {\n  height: 100%;\n  width: 100%;\n}\n\n.hero {\n  padding: 60px 20px;\n  width: 100%;\n  height: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: #f7f7f7;\n}\n\n.form {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  font-size: 1rem;\n}\n\n.input {\n  padding: 1rem 1.2rem;\n  margin: 1rem;\n  border-radius: 2rem;\n  display: block;\n  width: 80%;\n  border: none;\n  box-shadow: inset 6px 6px 8px rgba(97, 97, 97, 0.075),\n    6px 6px 6px rgba(255, 255, 255, 0.781);\n  outline: none;\n  background-color: inherit;\n  color: rgb(161, 161, 161);\n  font-size: inherit;\n}\n\n.submit , .btn {\n  margin-top: 20px;\n  font-weight: bold;\n  box-shadow: -3px -3px 5px white, 3px 3px 5px rgba(209, 209, 209, 0.705);\n  color: rgb(112, 112, 112);\n  cursor: pointer;\n}\n\n.btn {\n  text-align: center;\n  color: black;\n}\n\n.logo {\n  font-size: 3rem;\n  color: black;\n  font-weight: 600;\n  margin: 30px;\n}\n\n::placeholder {\n  color: rgb(161, 161, 161);\n}\n\n.forgotten {\n  text-align: center;\n  font-size: .8rem;\n  width: 80%;\n  color: gray;\n  margin: 15px 0;\n}\n\na {\n  color: inherit;\n  font-weight: bold;\n  text-decoration: none;\n}\n\n.or {\n  position: relative;\n  font-weight: bold;\n  color: rgb(112, 112, 112);\n}\n\n.or::before , .or::after {\n  position: absolute;\n  content: '';\n  width: 700%;\n  height: 1px;\n  top: 50%;\n  margin: 0 6px;\n  background-color: rgba(0, 0, 0, 0.479);\n}\n\n.or::before {\n  right: 100%;\n}\n\n.or::after {\n}\n\n.signup {\n  color: gray;\n  margin-top: 15px;\n  font-size: 1rem;\n}\n</style>\n"
