   "css": "\n/* From Uiverse.io by John-CFO - Tags: sign-in, form, sign-up, login , login form */\n.form {\n  position: relative;\n  display: block;\n  padding: 2.2rem;\n  max-width: 350px;\n  background: linear-gradient(14deg, rgba(2,0,36, 0.8) 0%, rgba(24, 24, 65, 0.7) 66%, \n            rgb(20, 76, 99) 100%), radial-gradient(circle, rgba(2,0,36, 0.5) 0%, \n            rgba(32, 15, 53, 0.2) 65%, rgba(14, 29, 28, 0.9) 100%);\n  border: 2px solid #fff;\n  -webkit-box-shadow: rgba(0,212,255) 0px 0px 50px -15px;\n  box-shadow: rgba(0,212,255) 0px 0px 50px -15px;\n  overflow: hidden;\n  z-index: +1;\n}\n\n/*------input and submit section-------*/\n\n.input-container {\n  position: relative;\n}\n\n.input-container input, .form button {\n  outline: none;\n  border: 2px solid #ffffff;\n  margin: 8px 0;\n  font-family: monospace;\n}\n\n.input-container input {\n  background-color: #fff;\n  padding: 6px;\n  font-size: 0.875rem;\n  line-height: 1.25rem;\n  width: 250px;\n  box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);\n}\n\n.input-mail:focus::placeholder {\n  opacity: 0;\n  transition: opacity .9s;\n}\n\n.input-pwd:focus::placeholder {\n  opacity: 0;\n  transition: opacity .9s;\n}\n\n.submit {\n  position: relative;\n  display: block;\n  padding: 8px;\n  background-color: #c0c0c0;\n  color: #ffffff;\n  text-shadow: 1px 1px 1px rgba(0, 0, 0, 0.5);\n  font-size: 0.875rem;\n  line-height: 1.25rem;\n  font-weight: 500;\n  width: 100%;\n  text-transform: uppercase;\n  overflow: hidden;\n}\n\n.submit:hover {\n  -webkit-transition: all 0.2s ease-out;\n  -moz-transition: all 0.2s ease-out;\n  transition: all 0.2s ease-out;\n  border-radius: 3.9px;\n  box-shadow: 4px 5px 17px -4px #ffffff;\n  cursor: pointer;\n}\n\n.submit:hover::before {\n  -webkit-animation: sh02 0.5s 0s linear;\n  -moz-animation: sh02 0.5s 0s linear;\n  animation: sh02 .5s 0s linear;\n}\n\n.submit::before {\n  content: '';\n  display: block;\n  width: 0px;\n  height: 85%;\n  position: absolute;\n  top: 50%;\n  left: 0%;\n  opacity: 0;\n  background: #fff;\n  box-shadow: 0 0 50px 30px #fff;\n  -webkit-transform: skewX(-20deg);\n  -moz-transform: skewX(-20deg);\n  -ms-transform: skewX(-20deg);\n  -o-transform: skewX(-20deg);\n  transform: skewX(-20deg);\n}\n\n@keyframes sh02 {\n  from {\n    opacity: 0;\n    left: 0%;\n  }\n\n  50% {\n    opacity: 1;\n  }\n\n  to {\n    opacity: 0;\n    left: 100%;\n  }\n}\n\n/*--------signup section---------*/\n\n.signup-link {\n  color: #c0c0c0;\n  font-size: 0.875rem;\n  line-height: 1.25rem;\n  text-align: center;\n  font-family: monospace;\n}\n\n.signup-link a {\n  color: #fff;\n  text-decoration: none;\n}\n\n.up:hover {\n  text-decoration: underline;\n}\n\n\n/*--------header section-----------*/\n\n.form-title {\n  font-size: 1.25rem;\n  line-height: 1.75rem;\n  font-family: monospace;\n  font-weight: 600;\n  text-align: center;\n  color: #fff;\n  text-shadow: 1px 1px 1px rgba(0, 0, 0, 0.7);\n  animation-duration: 1.5s;\n  overflow: hidden;\n  transition: .12s;\n}\n\n.form-title span {\n  animation: flickering 2s linear infinite both;\n}\n\n.title-2 {\n  display: block;\n  margin-top: -0.5rem;\n  font-size: 2.1rem;\n  font-weight: 800;\n  font-family: Arial, Helvetica, sans-serif;\n  text-align: center;\n  -webkit-text-stroke: #fff 0.1rem;\n  letter-spacing: 0.2rem;\n  color: transparent;\n  position: relative;\n  text-shadow: 0px 0px 16px #CECECE;\n}\n\n.title-2 span::before,\n.title-2 span::after {\n  content: '—';\n}\n\n@keyframes flickering {\n  0%,\n  100% {\n    opacity: 1;\n  }\n\n  41.99% {\n    opacity: 1;\n  }\n\n  42% {\n    opacity: 0;\n  }\n\n  43% {\n    opacity: 0;\n  }\n\n  43.01% {\n    opacity: 1;\n  }\n\n  47.99% {\n    opacity: 1;\n  }\n\n  48% {\n    opacity: 0;\n  }\n\n  49% {\n    opacity: 0;\n  }\n\n  49.01% {\n    opacity: 1;\n  }\n}\n\n/*---------shooting stars-----------*/\n\n\n.bg-stars {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  z-index: -2;\n  background-size: cover;\n  animation: animateBg 50s linear infinite;\n}\n\n@keyframes animateBg {\n  0%,100% {\n    transform: scale(1);\n  }\n\n  50% {\n    transform: scale(1.2);\n  }\n}\n\n.star {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  width: 4px;\n  height: 4px;\n  background: #fff;\n  border-radius: 50%;\n  box-shadow: 0 0 0 4px rgba(255,255,255,0.1),0 0 0 8px rgba(255,255,255,0.1),0 0 20px rgba(255,255,255,0.1);\n  animation: animate 3s linear infinite;\n}\n\n.star::before {\n  content: '';\n  position: absolute;\n  top: 50%;\n  transform: translateY(-50%);\n  width: 300px;\n  height: 1px;\n  background: linear-gradient(90deg,#fff,transparent);\n}\n\n@keyframes animate {\n  0% {\n    transform: rotate(315deg) translateX(0);\n    opacity: 1;\n  }\n\n  70% {\n    opacity: 1;\n  }\n\n  100% {\n    transform: rotate(315deg) translateX(-1000px);\n    opacity: 0;\n  }\n}\n\n.star:nth-child(1) {\n  top: 0;\n  right: 0;\n  left: initial;\n  animation-delay: 0s;\n  animation-duration: 1s;\n}\n\n.star:nth-child(2) {\n  top: 0;\n  right: 100px;\n  left: initial;\n  animation-delay: 0.2s;\n  animation-duration: 3s;\n}\n\n.star:nth-child(3) {\n  top: 0;\n  right: 220px;\n  left: initial;\n  animation-delay: 2.75s;\n  animation-duration: 2.75s;\n}\n\n.star:nth-child(4) {\n  top: 0;\n  right: -220px;\n  left: initial;\n  animation-delay: 1.6s;\n  animation-duration: 1.6s;\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n \n\n\n\n\n\n.submit.demo-tile[data-selected=\"true\"]{border-radius:3.9px;box-shadow:4px 5px 17px -4px #fff}",
