     "styleText": "\n/* From Uiverse.io by vinodjangid07 - Tags: purple, form, log in */\n.form_main {\n  width: 220px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  background-color: rgb(255, 255, 255);\n  padding: 30px 30px 30px 30px;\n  box-shadow: 0px 0px 40px rgba(0, 0, 0, 0.062);\n  position: relative;\n  overflow: hidden;\n}\n\n.form_main::before {\n  position: absolute;\n  content: \"\";\n  width: 300px;\n  height: 300px;\n  background-color: rgb(209, 193, 255);\n  transform: rotate(45deg);\n  left: -180px;\n  bottom: 30px;\n  z-index: 1;\n  border-radius: 30px;\n  box-shadow: 5px 5px 10px rgba(0, 0, 0, 0.082);\n}\n\n.heading {\n  font-size: 2em;\n  color: #2e2e2e;\n  font-weight: 700;\n  margin: 5px 0 10px 0;\n  z-index: 2;\n}\n\n.inputContainer {\n  width: 100%;\n  position: relative;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 2;\n}\n\n.inputIcon {\n  position: absolute;\n  left: 3px;\n}\n\n.inputField {\n  width: 100%;\n  height: 30px;\n  background-color: transparent;\n  border: none;\n  border-bottom: 2px solid rgb(173, 173, 173);\n  margin: 10px 0;\n  color: black;\n  font-size: .8em;\n  font-weight: 500;\n  box-sizing: border-box;\n  padding-left: 30px;\n}\n\n.inputField:focus {\n  outline: none;\n  border-bottom: 2px solid rgb(199, 114, 255);\n}\n\n.inputField::placeholder {\n  color: rgb(80, 80, 80);\n  font-size: 1em;\n  font-weight: 500;\n}\n\n#button {\n  z-index: 2;\n  position: relative;\n  width: 100%;\n  border: none;\n  background-color: rgb(162, 104, 255);\n  height: 30px;\n  color: white;\n  font-size: .8em;\n  font-weight: 500;\n  letter-spacing: 1px;\n  margin: 10px;\n  cursor: pointer;\n}\n\n#button:hover {\n  background-color: rgb(126, 84, 255);\n}\n\n.forgotLink {\n  z-index: 2;\n  font-size: .7em;\n  font-weight: 500;\n  color: rgb(44, 24, 128);\n  text-decoration: none;\n  padding: 8px 15px;\n  border-radius: 20px;\n}\n\n\n",
